namespace UniversityCourseCatalog.Models;

public class Department
{
    public int Id { get; set; }
    public string Name { get; set; } = string.Empty;
    public string Code { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
}

public class Course
{
    public int Id { get; set; }
    public int DepartmentId { get; set; }
    public string DepartmentCode { get; set; } = string.Empty;
    public string CourseNumber { get; set; } = string.Empty;
    public string Title { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public int Credits { get; set; }
    public string Schedule { get; set; } = string.Empty;
    public string InstructorName { get; set; } = string.Empty;
    public string InstructorBio { get; set; } = string.Empty;
    public bool IsFeatured { get; set; }

    public string FullCode => $"{DepartmentCode} {CourseNumber}";
}

public class EnrollmentRequest
{
    public string StudentName { get; set; } = string.Empty;
    public string StudentId { get; set; } = string.Empty;
    public int CourseId { get; set; }
}

using UniversityCourseCatalog.Models;

namespace UniversityCourseCatalog.Services;

public class CatalogService
{
    private readonly List<Department> _departments;
    private readonly List<Course> _courses;
    private readonly List<EnrollmentRequest> _enrollments = new();

    public CatalogService()
    {
        _departments = new List<Department>
        {
            new() { Id = 1, Code = "CS", Name = "Computer Science", Description = "Study of computation, algorithms, and information systems." },
            new() { Id = 2, Code = "MATH", Name = "Mathematics", Description = "Study of numbers, structures, and patterns." },
            new() { Id = 3, Code = "ENG", Name = "English", Description = "Study of literature, writing, and language." },
            new() { Id = 4, Code = "PHYS", Name = "Physics", Description = "Study of matter, energy, and the fundamental forces of nature." },
            new() { Id = 5, Code = "HIST", Name = "History", Description = "Study of past events and civilizations." }
        };

        _courses = new List<Course>
        {
            new() { Id = 1, DepartmentId = 1, DepartmentCode = "CS", CourseNumber = "101", Title = "Introduction to Programming", Description = "Learn the fundamentals of programming using Python. Topics include variables, control flow, functions, and basic data structures.", Credits = 3, Schedule = "Mon/Wed/Fri 9:00–9:50 AM", InstructorName = "Dr. Sarah Chen", InstructorBio = "Dr. Chen has 15 years of experience in software engineering and computer science education. She holds a PhD from MIT and has published extensively on programming pedagogy.", IsFeatured = true },
            new() { Id = 2, DepartmentId = 1, DepartmentCode = "CS", CourseNumber = "201", Title = "Data Structures and Algorithms", Description = "A comprehensive study of fundamental data structures and algorithm design techniques including trees, graphs, sorting, and dynamic programming.", Credits = 4, Schedule = "Tue/Thu 10:30–11:45 AM", InstructorName = "Dr. James Park", InstructorBio = "Dr. Park is a researcher in algorithm optimization with over 20 publications in top-tier journals. He earned his doctorate from Stanford University.", IsFeatured = true },
            new() { Id = 3, DepartmentId = 1, DepartmentCode = "CS", CourseNumber = "350", Title = "Database Systems", Description = "Design and implementation of relational databases. Covers SQL, normalization, indexing, and transaction management.", Credits = 3, Schedule = "Mon/Wed 2:00–3:15 PM", InstructorName = "Dr. Maria Rodriguez", InstructorBio = "Dr. Rodriguez spent 10 years in industry at major tech companies before joining academia. She specializes in distributed database systems.", IsFeatured = false },
            new() { Id = 4, DepartmentId = 2, DepartmentCode = "MATH", CourseNumber = "101", Title = "Calculus I", Description = "Introduction to differential calculus including limits, derivatives, and applications of differentiation.", Credits = 4, Schedule = "Mon/Wed/Fri 10:00–10:50 AM", InstructorName = "Dr. Alan Foster", InstructorBio = "Dr. Foster is an award-winning educator with a passion for making mathematics accessible. He has authored two widely-used calculus textbooks.", IsFeatured = true },
            new() { Id = 5, DepartmentId = 2, DepartmentCode = "MATH", CourseNumber = "201", Title = "Linear Algebra", Description = "Study of vector spaces, linear transformations, matrices, and eigenvalues with applications to science and engineering.", Credits = 3, Schedule = "Tue/Thu 1:00–2:15 PM", InstructorName = "Dr. Lisa Wang", InstructorBio = "Dr. Wang's research focuses on numerical linear algebra and its applications to machine learning. She joined the faculty from a research position at a national lab.", IsFeatured = false },
            new() { Id = 6, DepartmentId = 3, DepartmentCode = "ENG", CourseNumber = "110", Title = "College Writing", Description = "Develop essential academic writing skills through essays, research papers, and peer review workshops.", Credits = 3, Schedule = "Mon/Wed/Fri 11:00–11:50 AM", InstructorName = "Prof. David Kim", InstructorBio = "Prof. Kim is a published novelist and essayist who has taught writing at the university level for over a decade.", IsFeatured = false },
            new() { Id = 7, DepartmentId = 3, DepartmentCode = "ENG", CourseNumber = "250", Title = "American Literature", Description = "Survey of American literature from the colonial period to the present, exploring major authors and literary movements.", Credits = 3, Schedule = "Tue/Thu 9:00–10:15 AM", InstructorName = "Dr. Rachel Green", InstructorBio = "Dr. Green is a specialist in 20th-century American fiction. Her book on the Harlem Renaissance received the National Book Critics Circle Award.", IsFeatured = true },
            new() { Id = 8, DepartmentId = 4, DepartmentCode = "PHYS", CourseNumber = "101", Title = "General Physics I", Description = "Introduction to classical mechanics covering kinematics, Newton's laws, energy, momentum, and rotational motion.", Credits = 4, Schedule = "Mon/Wed/Fri 1:00–1:50 PM + Lab Thu 2:00–4:00 PM", InstructorName = "Dr. Robert Taylor", InstructorBio = "Dr. Taylor is an experimental physicist who has worked at CERN. He brings real-world research experience into the classroom.", IsFeatured = false },
            new() { Id = 9, DepartmentId = 4, DepartmentCode = "PHYS", CourseNumber = "220", Title = "Electromagnetism", Description = "Study of electric and magnetic fields, Maxwell's equations, electromagnetic waves, and optics.", Credits = 4, Schedule = "Tue/Thu 11:00 AM–12:15 PM + Lab Fri 2:00–4:00 PM", InstructorName = "Dr. Emily Zhang", InstructorBio = "Dr. Zhang's research is in quantum optics and photonics. She received the Young Physicist Award from the American Physical Society.", IsFeatured = false },
            new() { Id = 10, DepartmentId = 5, DepartmentCode = "HIST", CourseNumber = "101", Title = "World History to 1500", Description = "Survey of world civilizations from prehistory to the early modern period, covering major cultures, empires, and transformations.", Credits = 3, Schedule = "Tue/Thu 3:00–4:15 PM", InstructorName = "Dr. Michael Brown", InstructorBio = "Dr. Brown is a historian of the ancient world with archaeological field experience in the Mediterranean and Middle East.", IsFeatured = false },
            new() { Id = 11, DepartmentId = 5, DepartmentCode = "HIST", CourseNumber = "205", Title = "Modern European History", Description = "European history from the Enlightenment to the present, including revolutions, world wars, and the formation of the EU.", Credits = 3, Schedule = "Mon/Wed 10:00–11:15 AM", InstructorName = "Dr. Anna Schmidt", InstructorBio = "Dr. Schmidt specializes in 20th-century European political history. She was a visiting scholar at Oxford and the Sorbonne.", IsFeatured = true },
            new() { Id = 12, DepartmentId = 1, DepartmentCode = "CS", CourseNumber = "401", Title = "Machine Learning", Description = "Foundations of machine learning including supervised and unsupervised learning, neural networks, and model evaluation.", Credits = 3, Schedule = "Tue/Thu 3:30–4:45 PM", InstructorName = "Dr. James Park", InstructorBio = "Dr. Park is a researcher in algorithm optimization with over 20 publications in top-tier journals. He earned his doctorate from Stanford University.", IsFeatured = true }
        };
    }

    public List<Department> GetDepartments() => _departments;

    public Department? GetDepartment(int id) => _departments.FirstOrDefault(d => d.Id == id);

    public List<Course> GetAllCourses() => _courses;

    public List<Course> GetFeaturedCourses() => _courses.Where(c => c.IsFeatured).ToList();

    public List<Course> SearchCourses(string? searchTerm, int? departmentId)
    {
        var query = _courses.AsEnumerable();

        if (departmentId.HasValue && departmentId.Value > 0)
            query = query.Where(c => c.DepartmentId == departmentId.Value);

        if (!string.IsNullOrWhiteSpace(searchTerm))
        {
            var term = searchTerm.Trim().ToLowerInvariant();
            query = query.Where(c =>
                c.Title.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.FullCode.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.InstructorName.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Description.Contains(term, StringComparison.OrdinalIgnoreCase));
        }

        return query.ToList();
    }

    public Course? GetCourse(int id) => _courses.FirstOrDefault(c => c.Id == id);

    public List<Course> GetCoursesByDepartment(int departmentId) =>
        _courses.Where(c => c.DepartmentId == departmentId).ToList();

    public void SubmitEnrollment(EnrollmentRequest request)
    {
        _enrollments.Add(request);
    }
}

